"""Fifty individually reviewed CTB units, using the fresh protected baseline."""
import copy,json,sys
from pathlib import Path
root=Path(sys.argv[1]);old=json.loads((root/'batch-01-existing.json').read_text());expected={r['unit']['unit_key']:r for r in old};rows={}
CTB='https://www.planalto.gov.br/ccivil_03/leis/l9503compilado.htm'
L2020='https://www.planalto.gov.br/ccivil_03/_ato2019-2022/2020/lei/l14071.htm'
L2023='https://www.planalto.gov.br/ccivil_03/_ato2023-2026/2023/lei/l14599.htm'
L2024='https://www.planalto.gov.br/ccivil_03/_ato2023-2026/2024/lei/l14861.htm'
SENATRAN='https://www.gov.br/transportes/pt-br/assuntos/transito/senatran'
STJ='https://processo.stj.jus.br/repetitivos/temas_repetitivos/pesquisa.jsp?novaConsulta=true&tipo_pesquisa=T&cod_tema_inicial=965&cod_tema_final=965'
def add(n,case,variation,q1,q2,term,meaning,**patch):
 key='art-'+str(n);e=copy.deepcopy(expected[key]['explanation']);data={k:e[k] for k in ['simples','pontos','atencao','exemplo','prova','termos','remissoes']}
 data.update(exemplo=case+' Variação: '+variation,prova=[q1,q2],termos=[dict(termo=term,significado=meaning)])
 data['pontos']+=patch.pop('extra_points',[]);data['atencao']+=patch.pop('notes',[]);data['remissoes']=list(dict.fromkeys([CTB,*data['remissoes'],*patch.pop('sources',[])]));data.update(patch);rows[key]=data
add(1,'Uma falha de manutenção atribuída ao órgão competente causa dano ao usuário. Resposta: o §3º prevê responsabilidade objetiva, mas é necessário examinar competência, dano e nexo com a ação, omissão ou erro.', 'Um sinistro sem vínculo demonstrado com serviço do órgão não gera indenização automática apenas porque aconteceu numa via.', 'Somente carros em movimento integram o trânsito? Não. O §1º inclui pessoas e animais, além de circulação, parada, estacionamento e carga ou descarga.', 'Responsabilidade objetiva dispensa demonstrar dano e nexo? Não. O §3º vincula a responsabilidade aos danos decorrentes da atuação do órgão em suas competências.', 'Trânsito seguro','Direito de todos e dever dos integrantes do SNT no âmbito de suas competências.',extra_points=['Responsabilidade OBJETIVA no recorte do §3º não equivale a indenização automática por todo sinistro.','Prioridade: defesa da VIDA, abrangendo saúde e meio ambiente.'],notes=['Não criar obrigação com o §4º vetado nem afirmar responsabilidade universal de qualquer órgão por todo evento.'])
add(2,'Um motorista circula no estacionamento de um supermercado aberto ao público. Resposta: área privada de uso coletivo é considerada via terrestre para o CTB.', 'A aplicação do CTB não torna ilimitada toda atuação municipal ali: o art. 24, §3º, delimita a atribuição do inciso VI para infrações de uso de vagas reservadas.', 'O estacionamento privado de uso coletivo está fora do CTB? Não. O parágrafo único o inclui expressamente, junto às vias de condomínios e praias abertas à circulação pública.', 'Todo imóvel privado é automaticamente via aberta à circulação pública? Não. É preciso identificar a hipótese legal e o uso coletivo, sem generalizar o parágrafo.', 'Uso coletivo','Destinação que inclui vias e estacionamentos de estabelecimentos privados no recorte legal.',simples='O CTB abrange vias urbanas e rurais, praias abertas à circulação pública, vias internas de condomínios de unidades autônomas e vias e estacionamentos privados de uso coletivo. A circunscrição e as competências do órgão continuam relevantes.',extra_points=['ATUALIZAÇÃO: Lei 13.146/2015 incluiu expressamente vias e áreas de estacionamento de estabelecimentos privados de uso coletivo.'],notes=['Não confundir inclusão da via no CTB com competência irrestrita de qualquer autoridade; integrar art. 24, §3º.'])
add(3,'Uma turista dirige no Brasil um carro com registro estrangeiro. Resposta: o CTB também se aplica ao veículo e à condutora estrangeiros.', 'A aplicação do código não torna proprietário e condutor automaticamente responsáveis pela mesma infração; a atribuição da responsabilidade tem disciplina própria.', 'Veículos estrangeiros estão dispensados das regras de circulação brasileiras? Não. O art. 3º abrange expressamente veículos e condutores nacionais ou estrangeiros.', 'O art. 3º pune sempre proprietário e condutor juntos? Não. Define alcance do código; a responsabilidade por cada infração deve ser examinada nas regras pertinentes.', 'Alcance do código','Pessoas e veículos abrangidos, distinto da atribuição concreta de uma infração.',notes=['Não transformar o alcance geral em responsabilidade solidária automática por todas as condutas.'])
add(4,'Um candidato chama de parada qualquer imobilização de três minutos. Resposta: deve conferir a definição do Anexo I, que vincula parada ao tempo indispensável para embarque ou desembarque.', 'Carga e descarga não se tornam parada pela curta duração: o art. 47 as considera estacionamento.', 'Uma duração arbitrária de três minutos define parada? Não. O conceito legal deve ser buscado no Anexo I, integrado à regra específica.', 'O uso cotidiano de uma palavra substitui o conceito legal? Não. Para os efeitos do CTB, prevalecem as definições do Anexo I.', 'Definição legal','Sentido técnico adotado pelo CTB para aplicar suas regras.',notes=['Conferir o Anexo I atual; não recuperar definição antiga de categoria de veículo após alteração legislativa.'])
add(5,'A candidata estuda somente multas e esquece formação de condutores. Resposta: o SNT também exerce planejamento, pesquisa, educação, registro, habilitação, engenharia e outras atividades do artigo.', 'O julgamento de recursos integra o sistema, mas não significa que todo órgão tenha competência para julgar qualquer recurso.', 'O SNT é composto apenas por entidades federais? Não. Inclui União, Estados, Distrito Federal e Municípios.', 'Integrar o SNT concede todas as atribuições a cada integrante? Não. A finalidade do sistema não elimina a distribuição específica de competências.', 'Sistema integrado','Conjunto de órgãos de todos os entes, com funções complementares e competências próprias.',notes=['Distinguir finalidades do sistema e atribuições de cada órgão.'])
add(6,'Dois órgãos trocam permanentemente dados para decidir medidas de segurança. Resposta: o fluxo permanente de informações facilita decisões e integração do SNT.', 'A integração não permite abandonar critérios técnicos, financeiros e administrativos padronizados pelo inciso II.', 'A política nacional considera apenas rapidez do tráfego? Não. O inciso I reúne segurança, fluidez, conforto, defesa ambiental e educação.', 'O art. 6º contém um quarto inciso autônomo sobre intercâmbio? Não. Há três objetivos básicos; a integração está no inciso III, sem inventar inciso adicional.', 'Padronização','Critérios técnicos, financeiros e administrativos comuns para executar atividades de trânsito.',simples='O art. 6º tem três objetivos: diretrizes da política nacional e fiscalização de seu cumprimento; padronização de critérios técnicos, financeiros e administrativos; e fluxos permanentes de informações para decisão e integração.',notes=['Não transformar um resumo sobre aperfeiçoamento em quarto objetivo textual autônomo.'])
add(7,'Uma questão atribui ao Detran a posição de órgão máximo normativo do SNT. Resposta: essa posição é do Contran; órgãos executivos têm atribuições distintas.', 'Câmaras Temáticas assessoram tecnicamente o Contran pelo art. 13, mas não são inciso autônomo do rol do art. 7º.', 'O Contran é o órgão máximo executivo? Não. É coordenador e órgão máximo normativo e consultivo; a função executiva federal é distinta.', 'PRF, Polícias Militares e JARI aparecem no rol? Sim. São expressamente relacionados, cada qual com competências próprias.', 'Normativo e executivo','Produção de normas e execução de atividades são funções distintas no SNT.',simples='O art. 7º relaciona Contran; CETRAN e CONTRANDIFE; órgãos executivos de trânsito; órgãos executivos rodoviários; PRF; Polícias Militares; e JARI. Contran é coordenador e órgão máximo normativo e consultivo, não o órgão máximo executivo.',atencao=['Câmaras Temáticas são órgãos técnicos vinculados ao Contran no art. 13, sem inciso autônomo neste rol.','Não trocar Contran e Senatran nem atribuir competências indistintas a todos os integrantes.'],sources=[SENATRAN])
add('7-a','Autoridade portuária celebra convênio com órgão do SNT, com interveniência dos entes juridicamente interessados. Resposta: o instrumento facilita autuações em toda a área do porto organizado.', 'Terminal alfandegado ou estacionamento interno não está automaticamente fora da área alcançada pelo §1º.', 'O convênio vale somente para a via de entrada do porto? Não. O §1º abrange toda a área física, inclusive terminais, transbordo, instalações e estacionamentos ou vias internas.', 'O artigo afirma que toda autuação portuária é sempre inválida sem este convênio? Não. Cria possibilidade específica de cooperação; não elimina por presunção todas as competências ordinárias já existentes.', 'Interveniência','Participação dos Municípios e Estados juridicamente interessados no convênio específico.',atencao=['ATUALIZAÇÃO: incluído pela Lei 12.058/2009; não é redação original de 1997.','Poderá celebrar indica possibilidade legal; não ensinar exclusividade universal do convênio nem atribuir conteúdo aos §§2º e 3º vetados.'])
add(8,'Estado e Município organizam seus respectivos órgãos executivos e delimitam áreas de atuação. Resposta: o artigo atribui essa organização aos entes indicados.', 'Definir limites territoriais não permite criar por ato local uma competência contrária ao CTB.', 'O Presidente organiza diretamente todo órgão municipal de trânsito pelo art. 8º? Não. O artigo atribui a organização aos Estados, DF e Municípios.', 'Circunscrição equivale a liberdade para modificar qualquer competência legal? Não. Delimita atuação e precisa respeitar a distribuição de atribuições.', 'Circunscrição','Área delimitada de atuação do órgão, integrada à competência legal.',notes=['Não confundir área territorial com exclusividade universal sobre todas as atividades na via.'])
add(9,'Uma decisão administrativa diferencia Contran e órgão máximo executivo federal. Resposta: o art. 9º usa vinculação para o Contran e subordinação para o executivo.', 'É o Presidente da República quem designa o ministério ou órgão coordenador; o Contran não escolhe sozinho essa pasta.', 'Vinculação e subordinação foram usadas indistintamente no artigo? Não. O texto diferencia expressamente os dois vínculos.', 'Uma designação antiga de ministério deve ser memorizada como estrutura imutável? Não. O artigo contém regra de designação e a estrutura atual precisa ser consultada.', 'Coordenação máxima','Designação presidencial do ministério ou órgão da Presidência responsável pelo sistema.',notes=['A página institucional atual identifica Senatran no Ministério dos Transportes; distinguir texto legal e estrutura administrativa atual.'],sources=[SENATRAN])
add(10,'Um convidado tenta votar numa reunião do Contran. Resposta: não se confunde com Ministro membro ou representante qualificado do §4º; convidados do art. 10-A não votam.', 'Uma votação que reúne apenas maioria dos presentes pode ser insuficiente: o §6º exige maioria absoluta, não simples maioria relativa.', 'Qualquer servidor pode representar um Ministro? Não. O §4º exige nível igual ou superior a CCE 17, ou oficial-general quando militar.', 'O dirigente do órgão máximo executivo preside necessariamente o Contran? Não. É Secretário-Executivo; a presidência cabe ao Ministro indicado no §3º-A.', 'Maioria absoluta','Mais da metade da composição pertinente, diferente de maioria dos presentes.',simples='O Contran tem sede no DF e composição ministerial por áreas de competência. A Lei 14.599/2023 reorganizou a composição e a presidência. A representação dos Ministros exige CCE 17 ou superior, ou oficial-general quando militar; o dirigente do órgão máximo executivo é Secretário-Executivo. Votação e aprovação exigem maioria absoluta.',pontos=['Áreas: ciência/tecnologia/inovações, educação, defesa, meio ambiente, saúde, justiça, relações exteriores, indústria/comércio, agropecuária, transportes terrestres, segurança pública e mobilidade urbana.','Preside o Ministro ao qual está subordinado o órgão máximo executivo federal.','Representante: CCE 17 ou superior; hipótese militar: oficial-general.','Secretário-Executivo: dirigente do órgão máximo executivo. Quórum: MAIORIA ABSOLUTA.'],atencao=['ATUALIZAÇÃO: redação de 2023; não recuperar incisos revogados ou vetados como áreas ativas.','Convidado não é representante com voto; não trocar presidência e Secretaria-Executiva.'],sources=[L2023,L2020])
add('10-a','Representante de entidade setorial é convidado para explicar impacto de uma proposta. Resposta: pode participar, mas sem direito a voto.', 'Um servidor que representa formalmente Ministro sob o art. 10, §4º, está em categoria distinta do mero convidado.', 'O interesse da entidade na matéria dá voto ao convidado? Não. O art. 10-A exclui expressamente esse direito.', 'Convidado setorial e representante de Ministro são categorias iguais? Não. Observar o regime de convite e a representação qualificada do art. 10.', 'Convidado setorial','Participante responsável ou impactado pela matéria, sem voto nesse recorte.',atencao=['ATUALIZAÇÃO: redação atual da Lei 14.071/2020, com vigência diferida de 180 dias após publicação; já aplicável na conferência de 13/10/2026.','Não somar voto de convidado ao quórum legal.'],sources=[L2020])
add(12,'Uma proposta de norma ordinária é enviada à consulta pública por 20 dias. Resposta: o §1º exige período mínimo de 30 dias antes do exame pelo Contran.', 'Uma deliberação urgente e de relevante interesse público segue regime próprio: se não aprovada em 120 dias, perde eficácia, mas mantém os efeitos decorrentes; não pode ser reeditada.', 'As contribuições da consulta ficam disponíveis por somente 30 dias? Não. O §2º prevê dois anos após o encerramento da consulta.', 'A deliberação urgente se submete às mesmas regras dos §§1º e 2º? Não. O §4º, II, excepciona esse regime e veda reedição; urgência e relevante interesse público continuam necessários.', 'Ad referendum','Deliberação sujeita ao exame posterior do Plenário nos prazos e condições legais.',extra_points=['Contribuições: acesso público por DOIS ANOS contados do encerramento.','Urgência E relevante interesse público; 120 dias para aprovação, manutenção dos efeitos decorrentes e vedação de reedição.','§5º admite regulamentação de sinalização com técnicas de estímulos comportamentais para reduzir sinistros.'],notes=['Não afirmar que toda deliberação urgente já é resolução definitiva nem que a perda de eficácia apaga automaticamente efeitos anteriores.'],sources=[L2020,L2023])
add(13,'Especialistas estudam a segurança de ciclistas e oferecem subsídios ao Contran. Resposta: a Câmara Temática assessora; não substitui o colegiado na decisão normativa.', 'Há também especialistas de segmentos sociais representados por pessoas jurídicas que atendam aos requisitos; não restringir a Câmara aos servidores públicos.', 'A Câmara Temática edita por si a norma final do Contran? Não. Sua função legal é estudo, sugestão e embasamento técnico.', 'A coordenação pertence necessariamente a representante estadual? Não. O §3º prevê representante do órgão máximo executivo federal ou de Ministério representado no Contran, conforme o ato de criação.', 'Assessoramento técnico','Estudo especializado para subsidiar a decisão do Contran.',extra_points=['Sociedade: representação por pessoa jurídica e requisitos do Contran.','Coordenação definida no ato de criação, no recorte do §3º atualizado em 2020.'],notes=['Não atribuir conteúdo a incisos vetados ou transformar sugestão técnica em poder normativo final.'],sources=[L2020])
add(14,'A JARI rejeita recurso e a parte interpõe a segunda instância cabível ao CETRAN. Resposta: o inciso V prevê julgamento de recurso contra decisão da JARI, com o recorte pertinente.', 'O esgotamento da via administrativa do inciso V não impede, por si, controle judicial de ilegalidade.', 'CETRAN e CONTRANDIFE podem julgar recurso de inaptidão permanente nos exames indicados? Sim. O inciso V, b, prevê essa hipótese, distinta de recurso contra multa.', 'O parágrafo proíbe qualquer acesso ao Judiciário? Não. Refere-se à esfera administrativa nos casos do inciso V.', 'Instância administrativa','Exame dentro da Administração, distinto do controle jurisdicional.',notes=['Não generalizar o parágrafo único a todo ato dos Conselhos nem eliminar a via judicial.'])
add(15,'Governador nomeia pessoa com experiência em trânsito para integrar o CETRAN. Resposta: a competência de nomeação e a experiência são exigidas; mandato dos membros é de dois anos, com recondução admitida.', 'Ter experiência não transfere a nomeação ao Contran ou ao Presidente da República.', 'O mandato dos membros é de cinco anos sem recondução? Não. O §3º estabelece dois anos e admite recondução.', 'A experiência em trânsito é dispensável por livre nomeação? Não. Presidentes e membros devem atender ao requisito expresso.', 'Recondução','Nova permanência no mandato admitida pela lei, sem alterar a duração de dois anos.',extra_points=['Mandato dos MEMBROS: DOIS ANOS, admitida recondução.'],notes=['Não omitir o prazo nem confundir nomeação dos Conselhos estaduais/distrital com composição ministerial do Contran.'])
add(16,'Um órgão executivo aplica penalidade e o interessado recorre. Resposta: a JARI ligada ao órgão julga o recurso no recorte legal; defesa da autuação e recurso contra penalidade não são a mesma fase.', 'A JARI possui regimento próprio, mas deve respeitar as diretrizes do Contran e recebe apoio administrativo e financeiro do órgão.', 'A JARI julga recursos contra penalidades de qualquer órgão sem limite? Não. O art. 16 liga a Junta às penalidades do órgão junto ao qual funciona.', 'Regimento próprio permite ignorar diretrizes nacionais? Não. O regimento próprio deve observar as diretrizes do Contran previstas no art. 12, VI.', 'JARI','Colegiado administrativo recursal, distinto da autoridade que autua e aplica a penalidade.',notes=['Distinguir defesa da autuação, aplicação da penalidade e instâncias recursais; não inventar prazos neste artigo.'])
add(17,'A Junta encontra informação insuficiente no processo de recurso. Resposta: pode solicitar dados complementares ao órgão executivo para analisar a situação recorrida.', 'Um erro repetido em diversas autuações é comunicado ao órgão; isso não significa que a JARI passe a criar infrações novas.', 'Julgar é a única função da JARI neste artigo? Não. Também solicita informações e comunica problemas sistemáticos de autuação.', 'A informação complementar autoriza dispensar defesa ou fundamentação? Não. A instrução melhora análise do recurso e não elimina as garantias pertinentes.', 'Problema sistemático','Falha que se repete nas autuações e pode ser comunicada pela JARI.',notes=['Não transformar comunicação de falhas em competência para legislar sobre novas infrações.'])
add(19,'Uma candidata troca Renach e Renavam na prova. Resposta: Renach registra habilitações e Renavam veículos; o órgão máximo executivo federal mantém os registros nacionais previstos no artigo.', 'A consulta on-line do §5º abrange a própria habilitação e o veículo de propriedade do usuário; não é acesso irrestrito a dados pessoais de terceiros.', 'Uma deficiência estadual autoriza intervenção federal instantânea sem sindicância e sem Contran? Não. O §1º exige comprovação por sindicância e aprovação do Contran, até saneamento das irregularidades.', 'Os dados estatísticos previstos são fornecidos apenas uma vez por ano? Não. O §3º determina envio obrigatório mês a mês.', 'Registros nacionais','Renach: habilitações; Renavam: veículos; Renainf: infrações; RNPC: condutores positivos; Renaest: sinistros e estatísticas.',simples='A Senatran é identificada pelo portal oficial como órgão máximo executivo federal. O art. 19 reúne supervisão e execução da política, procedimentos, registros nacionais, estatísticas, educação e suporte ao Contran, com atribuições próprias e hipóteses de delegação. Consulta do §5º é dos dados da própria habilitação e do próprio veículo.',pontos=['RENACH, RENAVAM, RENAINF, RNPC e RENAEST possuem objetos distintos.','§1º: sindicância, deficiência/improbidade comprovada e aprovação do Contran para assumir atividades até saneamento.','§3º: fornecimento estatístico MÊS A MÊS.','§5º: consulta on-line do motorista/proprietário a seus dados, incluída pela Lei 14.861/2024.'],atencao=['ATUALIZAÇÃO: separar inclusão de Renaest em 2023 e consulta on-line em 2024 da data original do CTB.','Não confundir funções executivas/procedimentais da Senatran com posição normativa máxima do Contran, nem disponibilização dos próprios dados com publicidade irrestrita.','Lei 14.861: publicação em 28/5/2024 e vacância de 180 dias; esse período já transcorreu na conferência de 13/10/2026.'],sources=[SENATRAN,L2023,L2024])
add(20,'A PRF autua em rodovia federal e verifica infração com suspensão específica. Resposta: o inciso XII prevê aplicação dessa suspensão e comunicação ao órgão máximo executivo, dentro da competência legal.', 'A presença da PRF não elimina por si as atribuições do órgão executivo rodoviário do art. 21.', 'A PRF exerce só autuação, sem nenhuma penalidade? Não. O texto inclui advertência, multa e suspensão específica, além de medidas administrativas e outras atividades.', 'Este artigo estabelece competência exclusiva da PRF sobre qualquer órgão em toda rodovia federal? Não. Define seu âmbito, integrado às demais competências legais.', 'Patrulhamento ostensivo','Atuação da PRF no recorte legal de segurança pública e trânsito nas rodovias e estradas federais.',extra_points=['Suspensão específica da infração: inciso XII, com comunicação ao órgão máximo executivo federal.','Socorro, salvamento, estatísticas, perícia administrativa e prevenção não se confundem com função exclusivamente arrecadatória.'],notes=['Não trocar PRF por Polícia Federal nem extrair exclusividade universal de fiscalização; distinguir suspensão específica e processo por pontos.'],sources=[L2020,L2023,STJ])
add(21,'O DNIT fiscaliza infração de trânsito em rodovia federal dentro de suas atribuições. Resposta: o Tema 965/STJ reconhece competência não exclusiva; não excluir a autuação apenas porque a PRF também atua.', 'A fiscalização precisa continuar dentro da circunscrição e da competência pertinente; o entendimento não concede poder irrestrito em qualquer via.', 'Órgão executivo rodoviário cuida apenas de sinalização, sem autuar? Não. O art. 21 contempla fiscalização, penalidades, medidas e suspensão específica, além de outras funções.', 'O Tema 965 torna o DNIT fiscal exclusivo de toda rodovia federal? Não. A tese é expressamente não exclusiva e deve ser integrada aos limites legais.', 'Competência não exclusiva','Atribuição que não elimina automaticamente atuação válida de outro órgão competente.',atencao=['Não reduzir toda distribuição do CTB à frase rodoviário só em rodovia, executivo só em via urbana. Circunscrição, atividade e eventual delegação são relevantes.','Tema 965/STJ: competência do DNIT para fiscalização e penalidade em rodovias/estradas federais, em caráter NÃO EXCLUSIVO. O registro remete ao Tema 1077/STF; não se certifica aqui todo controle constitucional posterior.'],extra_points=['Inciso XV prevê suspensão específica com comunicação ao órgão máximo executivo federal.','Aplicação das funções rodoviárias exige o âmbito de circunscrição; não é exclusividade automática sobre todos os assuntos na via.'],sources=[STJ,L2020,L2023])
add(22,'Um condutor alcança o limite de pontos aplicável. Resposta: o processo estadual de suspensão está na hipótese do §1º, I; suspensão específica autuada pelo próprio órgão estadual está no inciso II.', 'Infração privativa municipal não se torna automaticamente estadual só porque a CNH foi expedida pelo Detran; verificar delegação válida quando pertinente.', 'O Estado fiscaliza indistintamente toda hipótese privativa municipal sem examinar convênio? Não. Os incisos V/VI ressalvam o art. 24, §4º, e o art. 24-A permite delegação mediante convênio.', 'Todo caso de suspensão específica pertence automaticamente ao Detran? Não. O §1º, II, exige autuação pelo próprio órgão executivo estadual nessa hipótese.', 'Competência privativa estadual','Recorte do art. 22, §2º, distinto da competência concorrente e sujeito à delegação legal cabível.',pontos=['Formação/habilitação e registro/licenciamento: observar a delegação federal expressa nos incisos II e III.','§1º: suspensão por pontos e suspensão específica quando autuada pelo próprio órgão estadual.','Privativas: arts. 165-D, 233, 240, 241, 242, 243 e art. 330, §5º.','Fiscalização e penalidades ressalvam as privativas municipais do art. 24, §4º.'],atencao=['ATUALIZAÇÃO: Lei 14.599/2023 reorganizou fiscalização e suspensão. Não recuperar a divisão antiga como vigente.','Integrar concorrência e possibilidade de delegar privativas por convênio; não inventar limites de pontos sem analisar art. 261 e seu caso.'],sources=[L2023,L2020])
add(23,'A Polícia Militar fiscaliza como agente do órgão de trânsito sob convênio vigente. Resposta: o inciso III condiciona essa atuação a quando e conforme o instrumento, junto aos demais agentes credenciados.', 'O convênio de trânsito não deve ser confundido com fundamento de todas as atribuições constitucionais da Polícia Militar.', 'A competência administrativa de fiscalização prevista aqui é universal e independe de convênio? Não. O inciso III exige fiscalização quando e conforme convênio, no recorte administrativo indicado.', 'Incisos vetados concedem competências adicionais atuais? Não. Veto não pode ser convertido em regra ativa ou exercício de competência inexistente.', 'Agente conveniado','Atuação administrativa no recorte e condições do convênio com o órgão competente.',notes=['A ressalva do convênio é para a fiscalização administrativa tratada no artigo; não declarar que toda atuação policial depende dele.'])
add(24,'Agente municipal verifica uso irregular de vaga reservada em estacionamento privado de uso coletivo. Resposta: a atuação do inciso VI ali tem o limite do §3º, sem competência universal para qualquer fato interno.', 'O município não passa a expedir CNH apenas porque exerce fiscalização ampla: habilitação segue a distribuição legal própria.', 'O município integrado ao SNT só pode sinalizar e nunca autuar? Não. O artigo prevê fiscalização, penalidades, medidas e outras competências.', 'A fiscalização municipal do inciso VI em edificação privada de uso coletivo alcança indistintamente toda infração? Não. O §3º limita esse exercício às infrações de uso de vagas reservadas.',pontos=['Competência municipal no DF: órgão executivo distrital (§1º).','Integração ao SNT: por órgão executivo ou diretamente pela prefeitura (§2º).','§3º limita atuação do inciso VI em edificação privada de uso coletivo a infrações de vagas reservadas.','Privativas municipais: arts. 95, 181, 182, 183, 218, 219, art. 231, V/X, e arts. 245, 246, 279-A; integrar delegação do art. 24-A.','Suspensão específica, educação, estacionamento rotativo e atividades próprias não equivalem a expedir CNH.'],atencao=['ATUALIZAÇÃO: Lei 14.599/2023 ampliou/reorganizou competências; não recuperar incisos VII/VIII revogados como rol atual separado.','A inclusão de estacionamento coletivo no CTB não elimina limites de competência. Não restringir hoje toda fiscalização municipal apenas a circulação, parada e estacionamento.'],sources=[L2023,L2020],term='Competência municipal',meaning='Funções próprias e concorrentes, no âmbito legal e com integração ao SNT.')
add('24-a','Estado e Município fiscalizam hipótese concorrente em suas competências. Resposta: o caput prevê concorrência, ressalvadas as listas privativas dos arts. 22 e 24.', 'Uma atividade privativa pode ser delegada por convênio do art. 25; privativa não significa indelegável em toda situação.', 'A concorrência elimina as listas privativas? Não. O artigo ressalva expressamente os dois recortes.', 'As privativas jamais podem ser delegadas? Não. O parágrafo único admite delegação por convênio do art. 25.', 'Concorrência e delegação','Atribuição compartilhada e transferência legal por instrumento próprio são conceitos distintos.',extra_points=['Parágrafo único admite delegação de competências privativas por CONVÊNIO.'],notes=['ATUALIZAÇÃO: incluído pela Lei 14.599/2023. Não equiparar concorrência, privatividade e indelegabilidade.'],sources=[L2023])
add(25,'Um Município sem órgão executivo celebra convênio diretamente pela prefeitura com integrante do SNT. Resposta: o §2º admite esse caminho e inclusive consórcio com outro ente federativo.', 'Uma mera combinação informal não substitui o convênio legal de delegação; capacitação/assessoria/monitoramento têm prazo e ressarcimento próprios.', 'A prefeitura sem órgão executivo está sempre impedida de celebrar convênio? Não. O §2º prevê expressamente sua celebração direta.', 'Capacitação e monitoramento devem ser necessariamente permanentes e gratuitos? Não. O §1º prevê prazo estabelecido entre as partes e ressarcimento dos custos apropriados.', 'Convênio de delegação','Instrumento de cooperação para atividades legais de trânsito, distinto de transferência informal de toda competência.',extra_points=['Prefeitura pode celebrar diretamente na falta de órgão executivo, inclusive por consórcio.'],notes=['Não afirmar que privativa é sempre indelegável nem que convênio elimina limites legais de atuação.'],sources=[L2020])
add('25-a','Agente da polícia legislativa, treinado e sob convênio, encontra infração nas adjacências do Congresso que compromete objetivamente o serviço. Resposta: pode lavrar auto e remetê-lo ao órgão competente no recorte legal.', 'A condição não se limita ao interior do prédio, mas também não permite autuar qualquer infração em toda Brasília sem os pressupostos.', 'A polícia legislativa recebe competência plena para julgar e aplicar qualquer penalidade por este artigo? Não. O artigo trata de lavrar auto e remetê-lo ao órgão competente, com condições específicas.', 'Treinamento específico é opcional? Não. O parágrafo exige treinamento conforme regulamentação do Contran.', 'Autuação legislativa delimitada','Lavratura e remessa do auto sob convênio, treinamento, local e comprometimento/risco previstos.',simples='Agentes das polícias da Câmara e Senado podem lavrar auto e remetê-lo ao órgão competente mediante convênio com quem tem circunscrição. A infração deve ocorrer nas adjacências do Congresso ou nos locais sob sua responsabilidade e comprometer objetivamente serviços ou colocar pessoas/patrimônio das Casas em risco. Exige treinamento específico.',pontos=['CONVÊNIO com órgão que tem circunscrição sobre a via.','Adjacências do Congresso OU locais sob responsabilidade das Casas.','Comprometimento objetivo de serviços OU risco à incolumidade/patrimônio.','Treinamento específico; lavrar e REMETER ao órgão competente.'],atencao=['ATUALIZAÇÃO: incluído pela Lei 14.071/2020 com vigência diferida. Não restringir às dependências internas nem atribuir poder pleno de trânsito sem os pressupostos.'],sources=[L2020])
add(26,'Um comerciante deixa entulho na pista e cria obstáculo ao tráfego. Resposta: o dever de não obstruir a via alcança usuários em geral, não somente motoristas.', 'O fato de ninguém ter colidido ainda não torna lícito criar perigo; o artigo previne risco e danos, respeitado o enquadramento sancionatório próprio.', 'Somente condutores devem evitar obstáculos na via? Não. O caput impõe os deveres aos usuários das vias terrestres.', 'O art. 26 fixa por si uma pena criminal automática? Não. É dever geral de conduta; eventual infração ou crime exige enquadramento e requisitos próprios.', 'Dever de prevenção','Evitar perigo, obstáculos e danos no trânsito, sem presumir sanção penal por todo descumprimento.',notes=['Não confundir dever geral, infração administrativa e crime de trânsito.'])
add(27,'Antes da viagem, a condutora encontra equipamento obrigatório sem funcionamento e combustível insuficiente. Resposta: deve regularizar as condições antes de colocar o veículo em circulação.', 'Ter combustível suficiente não dispensa conferir os equipamentos obrigatórios; são exigências distintas e cumulativas do artigo.', 'A verificação só precisa ocorrer depois de iniciar a viagem? Não. O dever é anterior à circulação nas vias públicas.', 'Este artigo exige tanque sempre cheio? Não. Exige combustível suficiente para chegar ao destino, além de equipamentos existentes e funcionando.', 'Verificação prévia','Conferência de equipamentos obrigatórios e combustível antes da circulação.',notes=['Não inventar percentual obrigatório do tanque nem listar equipamento sem conferir a regulamentação atual da categoria.'])
add(28,'Mesmo em rua vazia, o condutor se distrai e perde o controle da direção. Resposta: o dever de domínio, atenção e cuidado vale a todo momento.', 'Usar recurso de auxílio à condução não elimina por si o dever do condutor; o artigo não transfere automaticamente toda responsabilidade ao equipamento.', 'Ausência de outros veículos dispensa atenção? Não. O art. 28 exige domínio e cuidados a todo momento, não somente quando há tráfego intenso.', 'A simples referência ao art. 28 prova automaticamente qualquer crime de trânsito? Não. O dever geral não substitui os elementos específicos do tipo ou da infração.', 'Domínio do veículo','Controle contínuo da condução com atenção e cuidados de segurança.',notes=['Dever geral de cautela não equivale a condenação ou culpa automática em todo sinistro.'])
add(29,'Dois carros chegam a cruzamento não sinalizado e apenas um fluxo vem de rodovia. Resposta: tem preferência quem circula pela rodovia; em rotatória não sinalizada, quem já circula nela; nos demais casos, quem vem pela direita.', 'Uma ambulância em urgência usa os dispositivos regulamentares, mas chega ao cruzamento em alta velocidade sem cautela. A prioridade não elimina a obrigação de reduzir e proteger a segurança.', 'Todo veículo policial pode usar sirene em qualquer deslocamento? Não. A alínea c limita o uso de alarme e iluminação intermitente à efetiva prestação de serviço de urgência.', 'Utilidade pública em atendimento recebe automaticamente a mesma livre circulação de ambulância urgente? Não. O inciso VIII prevê parada e estacionamento no local do serviço, com identificação, não livre circulação universal.', 'Prerrogativa condicionada','Prioridade ou facilidade de circulação vinculada a finalidade, identificação e segurança legais.',simples='O art. 29 distribui circulação, distâncias, preferências, faixas, ultrapassagem e dever de proteção dos usuários vulneráveis. Veículos especiais têm prerrogativas condicionadas, não autorização para ignorar segurança. A Lei 14.071/2020 e a Lei 14.440/2022 atualizaram as regras; não copiar a antiga redação como vigente.',pontos=['Local não sinalizado: rodovia quando apenas um fluxo vem dela; rotatória para quem já circula; nos demais casos, veículo pela DIREITA.','Faixas: direita para lentos/maior porte, salvo faixa especial; esquerda para ultrapassagem e maior velocidade, sem afastar limites.','Ultrapassagem pela esquerda, salvo veículo à frente sinalizando entrada à esquerda; verificar quem já iniciou a manobra, faixa livre, distância e retorno seguro.','Passagem em passeio/calçada/acostamento no recorte do inciso V não é faixa livre de circulação.','Inciso VII: serviço de urgência, policiamento ostensivo ou preservação da ordem pública; uso de sirene/luz somente em efetiva urgência, com recortes de identificação das alíneas e/f.','Prioridade em via/cruzamento: velocidade REDUZIDA e cuidado; alarme não torna qualquer conduta segura.','Utilidade pública: parada/estacionamento no local do atendimento com identificação, sem livre circulação universal.','Trilhos: preferência respeitadas normas. Maior porte protege menor; motorizados protegem não motorizados; todos protegem pedestres.'],atencao=['Distinguir prerrogativas de circulação, parada, estacionamento e uso de dispositivos; não reduzir todas a uma condição genérica nem atribuir preferência absoluta sem cautela.','§4º prevê disciplina específica de veículos oficiais descaracterizados em situações especiais; não inventar dispensa geral automática.','Regras de ultrapassagem indicadas no §1º também se aplicam à transposição de faixas, que pode ocorrer pela direita ou esquerda.'],sources=[L2020])
add(30,'Um carro na faixa esquerda percebe o veículo de trás preparando ultrapassagem. Resposta: deve deslocar-se para a direita sem acelerar, com segurança.', 'Se já estiver em outra faixa, deve manter-se nela sem acelerar; não é ordem universal para trocar de faixa em todo caso.', 'O ultrapassado pode acelerar para impedir a manobra? Não. Tanto ao sair da faixa esquerda quanto ao manter outra faixa, o artigo exige não acelerar.', 'Veículos lentos em fila podem eliminar todo espaço entre si? Não. Devem manter distância que permita intercalação segura de quem os ultrapassa.', 'Cooperação na ultrapassagem','Conduta de quem é ultrapassado para permitir manobra segura, sem aceleração impeditiva.',notes=['A troca de faixa também deve respeitar cautela e sinalização; não converter cooperação em manobra arriscada.'])
add(31,'Um ônibus está parado desembarcando passageiros e uma pessoa surge ao seu lado. Resposta: quem pretende ultrapassá-lo reduz, redobra atenção e para se necessário à segurança.', 'Sem embarque ou desembarque, não se presume idêntico recorte do art. 31, mas permanecem os deveres gerais de segurança.', 'Basta passar normalmente pelo ônibus porque ele está parado? Não. A hipótese envolve embarque/desembarque e exige cautela reforçada.', 'O artigo manda sempre parar, sem examinar a situação? Não. Prevê redução com atenção redobrada ou parada para segurança dos pedestres.', 'Atenção redobrada','Cautela reforçada para proteger pedestres no embarque e desembarque.',notes=['Não confundir ônibus em simples estacionamento com a hipótese específica de embarque/desembarque.'])
add(32,'Em via de pista única e duplo sentido, o motorista chega a ponte sem sinalização que permita ultrapassar. Resposta: a proibição textual alcança a hipótese.', 'O artigo contém exceção de sinalização permissiva; ela não dispensa visibilidade, espaço e demais regras de segurança.', 'A confiança pessoal do motorista substitui a exceção sinalizada? Não. A exceção expressa é de sinalização permitindo a manobra.', 'Toda via, inclusive qualquer pista dupla, recebe automaticamente a mesma hipótese deste artigo? Não. Identificar pista única, duplo sentido e o local especificado, sem afastar outras proibições aplicáveis.', 'Ultrapassagem restrita','Manobra sujeita ao tipo de via, local, sinalização e cautela.',notes=['Não eliminar a exceção textual nem transformar uma sinalização permissiva em autorização contra toda regra de segurança.'])
add(33,'Perto de um cruzamento, o motorista inicia ultrapassagem porque a faixa parece livre. Resposta: o artigo proíbe a manobra na interseção e nas proximidades.', 'A exceção de sinalização do art. 32 não deve ser copiada automaticamente para o art. 33, que não a contém no seu texto.', 'Só dentro do centro geométrico do cruzamento vale a proibição? Não. A vedação também alcança as proximidades da interseção, sem depender de seu centro geométrico.', 'Via aparentemente vazia elimina a regra de proibição? Não. A ausência momentânea de veículo não cria exceção textual.', 'Interseção','Ponto de encontro de vias, com área próxima protegida contra ultrapassagem.',notes=['Não inventar distância fixa em metros para proximidades sem fonte regulamentar específica.'])
add(34,'A condutora liga a seta para mudar de faixa, mas há outro veículo aproximando-se pelo lado. Resposta: sinalizar não basta; precisa certificar-se de que a manobra não cria perigo.', 'A faixa estar livre atrás não dispensa observar usuários à frente e os que irão cruzar sua trajetória.', 'A seta concede preferência automática na manobra? Não. O dever de avaliar posição, direção e velocidade dos demais continua.', 'Só usuários que vêm atrás precisam ser considerados? Não. O artigo também abrange os que precedem e os que cruzarão.', 'Manobra segura','Mudança de movimento precedida de avaliação dos usuários e trajetórias.',notes=['Sinalização da intenção e segurança da execução são deveres distintos.'])
add(35,'A condutora pretende converter à direita e sinaliza antes da manobra de modo claro. Resposta: conversão é deslocamento lateral e exige antecedência.', 'Ligar a seta somente depois de começar a conversão não satisfaz o dever de antecedência; o gesto convencional previsto também não dispensa cuidado.', 'Retorno está fora do conceito de deslocamento lateral? Não. O parágrafo inclui retorno, conversões e transposição de faixas.', 'O CTB menciona exclusivamente luz indicadora, sem gesto de braço? Não. O texto prevê luz ou gesto convencional, observadas as demais exigências pertinentes.', 'Deslocamento lateral','Transposição de faixas, conversões à direita/esquerda e retornos.',notes=['Não confundir a indicação da intenção com autorização para executar manobra perigosa.'])
add(36,'Ao sair de uma garagem, o condutor encontra pedestre na via e carro já circulando. Resposta: deve dar preferência a ambos ao ingressar a partir do lote lindeiro.', 'A velocidade baixa de saída não concede preferência nem elimina o dever de observar o pedestre.', 'A preferência vale somente para os veículos da via? Não. Quem ingressa a partir de lote lindeiro deve ceder tanto aos veículos quanto aos pedestres da via.', 'Ser proprietário do imóvel torna preferencial sua saída? Não. A origem no lote lindeiro é justamente a hipótese que impõe ceder passagem.', 'Lote lindeiro','Imóvel adjacente à via, cuja saída exige ceder a quem nela transita.',notes=['Não trocar a regra de ingresso a partir de imóvel com a preferência em cruzamento não sinalizado.'])
add(37,'Em via com acostamento, o condutor quer retornar onde não existe local apropriado. Resposta: aguarda à direita no acostamento e só cruza com segurança, observadas outras restrições.', 'Se há local apropriado para conversão ou retorno, o artigo determina seu uso; não autoriza escolher sempre qualquer ponto do acostamento.', 'O texto manda aguardar no meio da pista? Não. A espera, na hipótese indicada, ocorre no acostamento à direita.', 'A existência de acostamento permite retorno proibido pela sinalização? Não. A regra precisa ser integrada aos limites e à segurança da manobra.', 'Acostamento','Parte da via utilizada no recorte de espera segura, sem virar faixa geral de circulação.',notes=['A hipótese não dispensa sinalização nem autoriza circular livremente no acostamento.'])
add(38,'Em via de sentido único, a condutora prepara conversão à esquerda. Resposta: aproxima-se do bordo esquerdo, não aplica automaticamente a posição do eixo de uma via de dois sentidos.', 'Ao converter, encontra ciclista e pedestre com passagem a respeitar: cede, além de observar veículos em sentido contrário e as preferências pertinentes.', 'A posição para sair à esquerda é igual em via de um e de dois sentidos? Não. O inciso II diferencia bordo esquerdo e eixo/linha divisória.', 'Durante a mudança de direção, só importa o veículo que vem atrás? Não. O parágrafo exige ceder a pedestres, ciclistas e veículos em sentido contrário, respeitadas preferências.', 'Posicionamento para conversão','Aproximação do bordo ou eixo pertinente, integrada à proteção de quem cruza a trajetória.',pontos=['Saída à DIREITA: aproximar-se do bordo direito e executar no menor espaço possível.','Saída à ESQUERDA: em dois sentidos, eixo/linha divisória; em sentido único, bordo esquerdo.','Ceder aos pedestres e ciclistas e aos veículos contrários conforme preferências.'],notes=['A seta e o posicionamento correto não concedem prioridade contra usuários com preferência.'])
add(39,'O condutor encontra local urbano sem proibição, mas a chuva e o movimento de ciclistas impedem retorno seguro. Resposta: a ausência de placa proibitiva não basta para autorizar a manobra.', 'Outro ponto oferece condições reais de segurança e fluidez no recorte do artigo; sua análise não se resume a ser formalmente sinalizado.', 'Retorno urbano só pode ocorrer em local com placa específica em toda hipótese? Não. O texto também admite locais apropriados e outros com segurança e fluidez, respeitadas restrições.', 'Basta a vontade de retornar para escolher qualquer ponto? Não. Considerar via, veículo, clima e movimento de pedestres e ciclistas.', 'Fluidez segura','Circulação sem interferência indevida, compatível com proteção dos usuários.',notes=['Não usar a possibilidade textual para desconsiderar sinalização proibitiva ou condições adversas.'])
add(40,'Um carro com luzes de rodagem diurna entra num túnel durante o dia. Resposta: a luz baixa continua obrigatória pelo inciso I, b; não basta invocar a regra de DRL da rodovia.', 'Em rodovia de pista simples fora do perímetro urbano, de dia e sem situação adicional, o §2º exige faróis para veículo sem DRL; motocicletas têm regra própria de luz baixa de dia e à noite.', 'A restrição fora da área urbana da buzina deve ser copiada para a troca intermitente de luzes? Não. O inciso III trata de intenção de ultrapassar o veículo à frente ou risco para o sentido contrário, sem a mesma condição territorial do art. 41, II.', 'Luz alta em via não iluminada pode ser mantida ao seguir outro veículo? Não. O inciso II exige a exceção ao cruzar ou seguir outro veículo.', 'Luz de rodagem diurna','DRL: iluminação com função própria, que não dispensa luz baixa nas hipóteses expressas.',simples='Usar luz baixa à noite e também de dia em túnel, chuva, neblina ou cerração. Via não iluminada exige luz alta, salvo cruzar ou seguir veículo. A troca intermitente breve tem hipóteses próprias de advertência; não copiar a limitação territorial da buzina. Os §§1º/2º distinguem motocicletas/transporte coletivo em faixa própria e veículos sem DRL em rodovia de pista simples fora do perímetro urbano.',pontos=['Luz baixa: noite; de dia em TÚNEL, CHUVA, NEBLINA ou CERRAÇÃO.','Luz alta em via não iluminada, exceto ao CRUZAR ou SEGUIR veículo.','Troca intermitente breve: intenção de ultrapassar o veículo à frente ou indicar risco aos veículos em sentido contrário.','Pisca-alerta: imobilizações/emergência ou determinação regulamentar da via.','À noite, luz de placa na circulação e luzes de posição na parada para embarque/desembarque/carga/descarga.','Motocicletas, motonetas e ciclomotores: luz baixa de dia e à noite; coletivo: recorte de faixa/pista destinada.','§2º: SEM DRL, em rodovia de PISTA SIMPLES, FORA do perímetro urbano, mesmo de dia.'],atencao=['ATUALIZAÇÃO: Lei 14.071/2020, com vigência diferida de 180 dias. Não recuperar inciso IV revogado nem regra antiga geral de farol diurno em toda rodovia.','DRL não afasta por si luz baixa em túnel ou condição meteorológica do inciso I. Não confundir troca de luzes com buzina.'],sources=[L2020])
add(41,'Fora da área urbana, a condutora dá toque breve para advertir que pretende ultrapassar. Resposta: é hipótese do inciso II, sem licença para buzina contínua.', 'Em área urbana, advertência necessária para evitar sinistro está no inciso I; mero cumprimento ou pressão para acelerar não se torna uso livre.', 'O artigo admite qualquer duração de toque nas hipóteses legais? Não. Mesmo nas hipóteses permitidas de advertência, o caput limita o uso a toque breve.', 'A advertência de ultrapassagem do inciso II vale indistintamente dentro de área urbana? Não. O inciso a condiciona a estar fora dessas áreas, distinto da prevenção de sinistros.', 'Advertência breve','Sinal sonoro curto nas hipóteses legais, distinto de uso livre ou prolongado.',notes=['ATUALIZAÇÃO: Lei 14.599/2023 usa sinistros no inciso I. O limite territorial da buzina de ultrapassagem não deve ser transportado ao art. 40, III.'],sources=[L2023])
add(42,'Um pedestre surge inesperadamente à frente e a condutora freia bruscamente para evitar atropelamento. Resposta: a exceção de segurança permite a frenagem necessária.', 'Frear para assustar o condutor que vem atrás não é legitimado pela mesma exceção e pode criar perigo.', 'O artigo proíbe qualquer frenagem brusca, inclusive para evitar sinistro? Não. A regra ressalva razões de segurança, como a frenagem necessária para evitar atropelamento.', 'Uma razão de vingança contra outro motorista equivale a segurança? Não. A exceção exige necessidade de segurança, não simples vontade de impor risco.', 'Exceção de segurança','Motivo legítimo para a frenagem brusca que a regra ordinária restringe.',notes=['Não ensinar proibição sem exceção nem presumir que toda frenagem provocativa é legítima.'])
add(43,'A velocidade máxima da via é 80 km/h, mas chuva intensa e visibilidade reduzida exigem velocidade menor. Resposta: respeitar o teto não dispensa adaptar a condução às condições.', 'Em via segura e fluxo normal, velocidade anormalmente reduzida sem causa justificada que obstrua veículos também viola o artigo; reduzir por risco real é situação diferente.', 'Circular no limite máximo assegura conformidade em qualquer clima? Não. Via, veículo, carga, clima e intensidade do trânsito devem ser considerados.', 'A verificação prévia ao reduzir nunca admite exceção? Não. O inciso II ressalva perigo iminente; a redução ordinária deve ser segura e sinalizada com antecedência.', 'Velocidade compatível','Ritmo adequado ao contexto, respeitado o limite máximo e a segurança.',extra_points=['Redução ordinária: avaliar risco/inconveniente e sinalizar com antecedência; ressalva de perigo iminente no inciso II.'],notes=['O limite máximo não é velocidade obrigatória. Não inventar uma velocidade mínima única para qualquer via neste artigo.'])
add(44,'A condutora tem preferência em cruzamento, mas um pedestre está na trajetória. Resposta: aproximação exige prudência e velocidade que permita parar com segurança, não preferência absoluta sem cautela.', 'Mesmo com semáforo favorável, a cautela se mantém; o art. 45 ainda impede bloquear o trânsito transversal.', 'Só cruzamento sem sinalização exige prudência especial? Não. O artigo abrange qualquer tipo de cruzamento.', 'Ter preferência permite atravessar sem observar pedestres? Não. O dever de controle e passagem segura continua.', 'Prudência no cruzamento','Cautela reforçada para conseguir parar e respeitar quem deve passar.',notes=['Preferência não elimina o dever de segurança; não tratar o sinal favorável como autorização incondicional.'])
add('44-a','Há sinalização permitindo conversão à direita no vermelho e a área de destino está livre. Resposta: a conversão pode ocorrer com prudência, sem prejudicar pedestres e sem bloquear a interseção.', 'Sem sinalização permissiva, a simples ausência de veículos não cria essa autorização; com pedestre em situação protegida, deve ceder.', 'A Lei 14.071 liberou toda conversão à direita em qualquer vermelho? Não. Exige sinalização indicativa permitindo e observância dos arts. 44, 45 e 70.', 'A autorização permite fechar o cruzamento ou ignorar a preferência do pedestre? Não. As remissões preservam cautela, não bloqueio e proteção dos pedestres.', 'Conversão condicionada','Permissão expressamente sinalizada, integrada às demais regras de segurança.',notes=['ATUALIZAÇÃO: incluído pela Lei 14.071/2020, vigente após sua vacância. Não copiar permissões gerais de outros países nem transformar a placa em prioridade absoluta.'],sources=[L2020])
add(45,'O semáforo está verde, mas o trânsito à frente impede sair da área do cruzamento. Resposta: não deve entrar, pois pode ficar imobilizado e impedir o fluxo transversal.', 'Na abertura de espaço suficiente, a passagem volta a ser examinada com as regras e cautelas pertinentes; não há proibição permanente de cruzar por ter havido fila.', 'Sinal verde autoriza entrar mesmo com risco de parar bloqueando a interseção? Não. O artigo ressalva essa situação expressamente.', 'Só depois de efetivamente bloquear a via surge o dever de cautela? Não. A regra considera a possibilidade de imobilização na área do cruzamento.', 'Não bloqueio','Dever de preservar o fluxo transversal, mesmo com sinal luminoso favorável.',notes=['O dever decorre do risco de obstrução; não presumir preferência ilimitada pelo verde.'])
add(46,'Um veículo sofre pane e precisa imobilizar-se temporariamente no leito viário. Resposta: é necessária sinalização imediata de advertência, conforme forma estabelecida pelo Contran.', 'Ativar um equipamento não deve ser tratado como cumprimento automático de toda regra regulamentar; examinar os requisitos atuais e a situação concreta.', 'A emergência dispensa sinalizar porque a parada era inevitável? Não. É precisamente a hipótese que exige advertência imediata.', 'O art. 46 fixa sozinho uma distância universal de triângulo? Não. Remete a forma de sinalização ao Contran; não inventar metragem sem verificar a norma pertinente.', 'Advertência de emergência','Sinalização imediata de imobilização no leito viário, integrada à regulamentação.',notes=['Não certificar neste artigo todo detalhe de equipamento ou distância regulamentar; emergência não afasta o dever de segurança.'])
add(47,'Uma pessoa embarca rapidamente em local que proíbe estacionamento, sem interromper o fluxo. Resposta: a parada se limita ao tempo indispensável de embarque/desembarque, respeitadas outras proibições.', 'Descarregar mercadorias durante apenas dois minutos continua sendo estacionamento para o parágrafo; curta duração não transforma carga/descarga em parada.', 'Toda parada é permitida onde estacionamento é proibido? Não. O recorte exige embarque/desembarque indispensável e ausência de interrupção ou perturbação do fluxo de veículos/pedestres, além das restrições pertinentes.', 'Carga e descarga viram parada se o motorista continua dentro do veículo? Não. O parágrafo as considera estacionamento e remete a regulamentação ao órgão com circunscrição.', 'Parada e estacionamento','Embarque/desembarque indispensável e carga/descarga têm tratamento jurídico distinto.',notes=['Proibição de estacionar não permite parada em local onde também exista proibição de parar ou em condição que perturbe o fluxo.'])
rows['art-13']['simples']='Câmaras Temáticas são órgãos técnicos vinculados ao Contran, com especialistas que oferecem estudo, sugestões e embasamento para suas decisões. O §1º reúne representantes da União, dos Estados OU do DF e dos Municípios em igual número, além de segmentos sociais. Coordenação e designação seguem os recortes do artigo e do ato de criação.'
rows['art-22']['simples']='O órgão executivo estadual ou distrital controla formação e habilitação, expede e cassa Licença de Aprendizagem, Permissão para Dirigir e CNH, e registra, emplaca e licencia veículos no recorte de delegação federal. Fiscalização, penalidades e suspensão devem observar a reorganização de 2023, as privativas municipais e o art. 24-A; não atribuir cassação de todo documento veicular ao inciso III.'
rows['art-24']['simples']='O órgão municipal integrado ao SNT planeja e opera o trânsito, implanta sinalização e exerce fiscalização, penalidades e medidas dentro de suas competências. A Lei 14.599/2023 reorganizou concorrência e privativas. A atuação do inciso VI em edificação privada coletiva tem limite específico de vagas reservadas; outras atribuições não se confundem com expedir CNH.'
rows['art-17']['pontos'].append('Comunicar problemas de autuação que se repitam sistematicamente, no recorte do inciso III.')
assert len(rows)==50 and set(rows)==set(expected)
for key,row in rows.items():
 assert 'Variação:' in row['exemplo'] and len(row['prova'])==2
 assert all('?' in q and len(q.split('?',1)[1].strip())>45 for q in row['prova']),key
 assert row['termos'] and all(t['significado'] for t in row['termos'])
Path(sys.argv[2]).write_text(json.dumps({'course_slug':'transito','units':rows},ensure_ascii=False,indent=2)+'\n')
print('50 explicitly reviewed CTB units')
